import type { TypedJSONRPCClient } from "json-rpc-2.0";

export interface OkResponse {
  status: "OK";
}

export interface AnalyseResponse {
  frames: number;
  protocols: string[];
  first?: number;
  last?: number;
}

export interface ByeResponse extends OkResponse {}

export interface CheckRequest {
  field?: string;
  filter?: string;
}

export interface CheckResponse extends OkResponse {}

export interface CompleteRequest {
  field?: string;
  pref?: string;
}

export interface CompleteResponse {
  field?: {
    f: string; // field_reference
    t: string; // field_type
    n: string; // field_name
  }[];
  pref?: {
    f: string; // preference_name
    d: string; // preferece_description
  }[];
}

export interface DumpConfRequest {
  pref?: string;
}

export type DumpConfResponse = {
  prefs: {
    [key: string]: {
      b: number; // binary value
      d: string; // description
      e: {
        // drop down
        v: number; // index
        s?: number; // selected
        d: string; // description
      }[];
      r: string; // range value
      s: string; // string value
      t: string[][]; // table value
      u: number; // unsigned int value
    };
  };
};

export interface FrameRequest {
  frame: number; // frame number
  proto?: true; // if present output protocol tree
  columns?: true; // if present overwrites default columns of profile
  color?: true; // if present output color-filter bg/fg
  bytes?: true; // if present output frame bytes
  hidden?: true; // if present output hidden tree fields
}

export type ByteRange = [number, number];

export interface TreeNode {
  h: ByteRange; // byte start index, byte length
  l: string; // field label
  t: "proto" | "framenum" | "url"; // type of tree or subtree node
  f: string; // filter variable - can be used in filter expression
  s: string; // severity
  e: number; // subtree ett index
  n: TreeNode[]; // array of subtree nodes
  url: string;
  fnum: number; // used to reference in the file
  g: boolean; // true if field is generated by wireshark
  v: boolean; // true if field is hidden
}

export interface FrameResponse {
  tree?: TreeNode[];
  col?: string[];
  bytes?: string; // base64 encoded packet bytes
  comment?: string; // frame comment
  bg?: string; // background color in hex
  fg?: string; // foreground color in hex
}

export interface FramesRequest {
  [key: `column${number}`]: string | number;
  filter?: string; // display filter
  skip?: number; // skip n frames
  limit?: number; // limit output to n frames
  refs?: string; // comma separated list of frame numbers
}

export interface FramesResponse {
  c: string[];
  num: number;
  bg: string;
  fg: string;
}

export interface InfoResponse {
  columns: { name: string; format: string }[];
  stats: [];
  ftypes: [];
  version: string;
  nstat: [];
  convs: [];
  sequ: [];
  taps: [];
  eo: [];
  srt: [];
  rtd: [];
  follow: [];
}

export interface LoadRequest {
  file: string;
}

export interface LoadResponse extends OkResponse {}

export interface StatusResponse {
  frames: number; // count of currently loaded frames
  duration: number; // time diff between first frame and last loaded frame
  filename?: string; // only present if a file is loaded
  filesize?: number; // in bytes
}

// https://wiki.wireshark.org/sharkd-JSON-RPC#request-types
export type SharkdMethods = {
  analyse: () => AnalyseResponse;
  bye: () => ByeResponse;
  check: (params: CheckRequest) => CheckResponse;
  complete: (params: CompleteRequest) => CompleteResponse;
  dumpconf: (params: DumpConfRequest) => DumpConfResponse;
  frame: (params: FrameRequest) => FrameResponse;
  frames: (params: FramesRequest) => FramesResponse[];
  info: () => InfoResponse;
  load: (params: LoadRequest) => LoadResponse;
  status: () => StatusResponse;
};

export type SharkdClient = TypedJSONRPCClient<SharkdMethods>;
